/**
 * Authority is a registry office.
 *
 * It must be an x/group account, for the same reason x/land requires it: an
 * office that is one key is one bribe, and enrolling a herd, certifying
 * parentage and validating a transfer are each a single signature otherwise.
 */
export interface Authority {
  address: string;
  name: string;
  jurisdiction: string;
  active: boolean;
}

/**
 * Attestation is one accredited agent swearing that the animal presented is
 * the animal on the record.
 *
 * This is the only claim in the whole system that the chain cannot check for
 * itself, and the reason the four-party shape exists: seller, buyer, registry
 * and somebody who physically looked at the animal.
 */
export interface Attestation {
  attestor: string;
  /**
   * The office the attestor answers to, captured at attestation time. Recorded
   * rather than looked up later because an attestor can be struck off, and the
   * question "was this independent when it was made" has to stay answerable.
   */
  authority: string;
  /**
   * Hash of what they actually checked — the tag read back, a photograph taken
   * at the time. A false attestation should be a specific claim by a named
   * person, not a shrug.
   */
  evidenceHash: string;
  /**
   * Unix SECONDS, not a block height. See Herd.registered_at for why this
   * module carries both kinds of int64 and why confusing them prints 1970.
   */
  attestedAt: string;
}

/**
 * Transfer is a supervised handover of one animal.
 *
 * The mechanism is the same one x/land uses for a parcel, and for the same
 * reason: it is not there to trace a theft afterwards, it is there to make the
 * lawful resale of a stolen animal impossible, which is what destroys its
 * value. A thief can still take the beast. He cannot sell it with a title.
 */
export interface Transfer {
  id: string;
  animalId: string;
  from: string;
  to: string;
  /**
   * Free text, and not enforced by the chain. The registry records what the
   * parties say they agreed; it does not hold the money and does not pretend
   * to have witnessed the payment.
   */
  price: string;
  state: TransferState;
  attestations: Attestation[];
  /**
   * When the attestation quorum was reached. The challenge window runs from
   * this, not from the proposal — otherwise a transfer could be proposed
   * quietly, left to age, and completed the moment it was attested.
   * Unix SECONDS, not a block height. See Herd.registered_at for why this
   * module carries both kinds of int64 and why confusing them prints 1970.
   */
  attestedAt: string;
  objectedBy: string;
  objectionReason: string;
  /**
   * Unix SECONDS, not a block height. See Herd.registered_at for why this
   * module carries both kinds of int64 and why confusing them prints 1970.
   */
  proposedAt: string;
  /**
   * Who resolved the objection, and what they decided. An objection can be
   * raised by anybody, so it has to be answerable by somebody — and the answer
   * is recorded rather than merely applied, because the interesting pattern is
   * not one dismissal, it is an office that dismisses every objection raised
   * against one seller.
   */
  resolvedBy: string;
  resolutionReason: string;
  /**
   * True where the office found the objection had substance. Kept as a field
   * rather than inferred from the state, because a dismissed objection returns
   * the transfer to the state it was in and would otherwise leave no trace
   * that it had ever been raised.
   */
  objectionUpheld: boolean;
  /**
   * When the buyer agreed. Needed to put a transfer back where it was after an
   * objection is dismissed: the state alone was overwritten by OBJECTED, and
   * guessing from the attestation count cannot tell a proposal nobody accepted
   * from one that was accepted and not yet attested.
   * Unix SECONDS, not a block height. See Herd.registered_at for why this
   * module carries both kinds of int64 and why confusing them prints 1970.
   */
  acceptedAt: string;
}

